package local.mediacenter.library
import org.json.JSONObject
import org.junit.Test
import org.junit.Assert.*
class MusicTransitionPlanTest {
 @Test fun repeatedOpenFileNeverGetsAConcurrentDescriptorReader(){assertTrue(MusicTransitionPlan.sharedDescriptor(true,true));assertFalse(MusicTransitionPlan.sharedDescriptor(false,true));assertFalse(MusicTransitionPlan.sharedDescriptor(true,false))}
 @Test fun originalPreservingDefaultsAndStrictSettings(){assertTrue(MusicTransitions.parse(JSONObject()).gapless);assertEquals(0.0,MusicTransitions.parse(JSONObject()).crossfade,0.0);for(r in listOf(JSONObject().put("crossfade",-1),JSONObject().put("crossfade",13),JSONObject().put("gapless","yes"),JSONObject().put("crossfade","5"),JSONObject().put("crossfade",JSONObject.NULL)))assertTrue(runCatching{MusicTransitions.parse(r)}.isFailure)}
 @Test fun booksEpisodesRadioAndTimersCannotOverlapOrPreload(){assertTrue(MusicTransitionPlan.eligible("music","local",false,0.0,false));for(kind in listOf("book","podcast","radio","movie","videoEpisode")){assertFalse(MusicTransitionPlan.eligible(kind,"music",false,0.0,false));assertFalse(MusicTransitionPlan.eligible("music",kind,false,0.0,false))};assertFalse(MusicTransitionPlan.eligible("music","music",true,0.0,false));assertFalse(MusicTransitionPlan.eligible("music","music",false,20.0,false));assertFalse(MusicTransitionPlan.eligible("music","music",false,0.0,true))}
 @Test fun nextOccurrenceRespectsRepeatQueueBoundaryAndStableShuffleChoice(){assertEquals(2,MusicTransitionPlan.next(1,3,"off",false));assertNull(MusicTransitionPlan.next(2,3,"off",false));assertEquals(0,MusicTransitionPlan.next(2,3,"all",false));assertEquals(1,MusicTransitionPlan.next(1,3,"one",true));assertEquals(2,MusicTransitionPlan.next(1,3,"off",true){it.last()});assertNull(MusicTransitionPlan.next(0,0,"all",false))}
 @Test fun fadesShortenForBothTracksAndPlaybackSpeed(){assertEquals(2.0,MusicTransitionPlan.fadeSeconds(12.0,8.0,4.0,1.0),0.0);assertEquals(1.0,MusicTransitionPlan.fadeSeconds(12.0,8.0,4.0,2.0),0.0);assertEquals(0.0,MusicTransitionPlan.fadeSeconds(5.0,1.0,30.0,1.0),0.0);assertEquals(0.0,MusicTransitionPlan.fadeSeconds(5.0,30.0,30.0,0.0),0.0)}
 @Test fun complementaryEnvelopeNeverBoostsCorrelatedPeaks(){for(n in -10..110){val (out,inside)=MusicTransitionPlan.gains(n/100.0);assertTrue(out in 0.0..1.0&&inside in 0.0..1.0);assertEquals(1.0,out+inside,.000001)};assertEquals(1.0 to 0.0,MusicTransitionPlan.gains(0.0));assertEquals(0.0 to 1.0,MusicTransitionPlan.gains(1.0))}
 @Test fun envelopeCompletesOnlyAfterItsEntirePresentationTime(){val clock=MusicFadeClock(2.0,1000);assertEquals(.7,clock.step(2400,true),.000001);assertEquals(.95,clock.step(2900,true),.000001);assertEquals(1.0,clock.step(3000,true),.000001);assertEquals(1.0,clock.step(3500,true),.000001)}
 @Test fun pauseFreezesBothFadeGainsUntilPlaybackResumes(){val clock=MusicFadeClock(2.0,1000);assertEquals(.25,clock.step(1500,true),0.0);assertEquals(.25,clock.step(15000,false),0.0);assertEquals(.5,clock.step(15500,true),0.0)}
 @Test fun fadeClockIgnoresBackwardTimeAndCatchesUpAfterWorkerDelay(){val clock=MusicFadeClock(2.0,1000);assertEquals(.25,clock.step(1500,true),0.0);assertEquals(.25,clock.step(1200,true),0.0);assertEquals(.5,clock.step(2000,true),0.0);assertEquals(1.0,clock.step(4000,true),0.0)}
 @Test fun prefetchCannotReuseAnotherAccountsAuthenticationContext(){assertTrue(MusicTransitionPlan.prefetch("one","Bearer a","one","Bearer a"));assertFalse(MusicTransitionPlan.prefetch("one","Bearer a","two","Bearer a"));assertFalse(MusicTransitionPlan.prefetch("one","Bearer a","one","Bearer b"));assertFalse(MusicTransitionPlan.prefetch("one","Bearer a","one",""))}
}
